  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- shakespeares-restaurant-durbanville (researched)
UPDATE businesses SET description = 'Shakespeare''s is a restaurant in Heritage Square on Vrede Street in Durbanville, Cape Town, with a theatrical theme. It is a re-imagining of a 50-year-old Durbanville establishment, and it serves breakfast, lunch, dinner and high tea. The concept is fine food, good wine and entertainment for grown-ups.

The interior uses old furnishings and crockery brought in from around the country, and the restaurant displays a 404-year-old bible and a 90-year-old baby grand piano. The menu follows the theme, with a main dish named after a quote from The Merchant of Venice and a dessert named after Hamlet. Nightly performances are part of the evening. It suits diners who want an evening out with food and theatre.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.capetownmagazine.com/shakespeares'), description_enriched_at = datetime('now') WHERE slug = 'shakespeares-restaurant-durbanville' AND description = 'Shakespeare''s Restaurant is a fine-dining restaurant in Heritage Square, Durbanville, reimagining a decades-old Durbanville establishment with an Elizabethan theatre-of-dining theme, offering breakfast, lunch, dinner and high tea.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
