-- shift-espresso-bar-green-point (researched)
UPDATE businesses SET description = 'Shift Espresso Bar is a specialty coffee shop and cafe on Main Road in Green Point, opened in June 2014 with an industrial-style interior of exposed copper light fittings and metal shelving. Beyond the expected cappuccinos, lattes, flat whites and Americanos, the bar built its name on its own specialty coffee creations, alongside cafe food and all-day seating for customers who want to linger.

The cafe positions itself around coffee, food, service and the overall customer experience, with free Wi-Fi, laptop plug points and charging stations making it as practical for a work session as for a quick coffee. It suits Green Point locals and visitors looking for a relaxed, informal spot to work, meet or simply enjoy a well-made coffee.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.capetownmagazine.com/shift-espresso-bar', '$[#]', 'https://www.shiftespresso.com/'), description_enriched_at = datetime('now') WHERE slug = 'shift-espresso-bar-green-point' AND description = 'Shift Espresso Bar is a specialty coffee shop on Main Road in Green Point, established in 2014 and known for signature espresso drinks in an industrial-style interior.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
